  ;(api as StoreApi<S> & StorePersist<StoreApi<S>, S, unknown>).persist = {
    setOptions: (newOptions) => {
      options = {
        ...options,
        ...newOptions,
      }

      if (newOptions.storage) {
        storage = newOptions.storage
      }
    },
    clearStorage: () => {
      ++hydrationVersion
      storage?.removeItem(options.name)
